//! Since the actual message structs are generated by other macros, we cannot practically import
//! that context here. We can however have the base names as input, and go from there

use crate::common::parse_property_colon_member;
use crate::templates::Unparse;
use heck::{ToPascalCase, ToSnakeCase};
use proc_macro2::{Ident, TokenStream};
use quote::{format_ident, quote};
use syn::parse::{Parse, ParseStream};
use syn::{bracketed, Token};

mod kw {
    syn::custom_keyword!(group_name);
    syn::custom_keyword!(categories);
}

pub struct GroupedRequestResponseCategoryTemplate {
    pub group_name: Ident,
    pub generator: GroupedRequestResponseCategoryRustStructGenerator,
}

/// Expected pattern:
/// {
///     group_name: GroupName,
///     categories: {
///        category_name: macro_name
///     }
/// }

impl Parse for GroupedRequestResponseCategoryTemplate {
    fn parse(input: ParseStream) -> syn::Result<Self> {
        let group_name = parse_property_colon_member::<kw::group_name, Ident>(input)?;
        let generator = parse_property_colon_member::<kw::categories, GroupedRequestResponseCategoryRustStructGenerator>(input)?;

        if !input.is_empty() {
            return Err(input.error("unexpected tokens in grouped request response category"));
        }

        Ok(Self { group_name, generator })
    }
}

impl Unparse for GroupedRequestResponseCategoryTemplate {
    /// Re-emit `group_name` and `Categories` so the template can be parsed again.
    fn unparse(&self) -> TokenStream {
        let group_name = &self.group_name;
        let categories = self.generator.unparse();
        quote! {
            group_name: #group_name,
            categories: #categories,
        }
    }
}

impl GroupedRequestResponseCategoryTemplate {
    pub fn generate_generic_with_field_name_categories_and_of_type(&self) -> proc_macro2::TokenStream {
        self.generator.generate_generic_with_field_name_categories_and_of_type(&self.group_name)
    }
}

pub struct GroupedRequestResponseCategoryRustStructGenerator {
    categories: Vec<GroupedRequestResponseCategoryRustStructNames>,
}

/// Expected pattern:
/// categories: {
///    category_name: macro_name
/// }
impl Parse for GroupedRequestResponseCategoryRustStructGenerator {
    fn parse(input: ParseStream) -> syn::Result<Self> {
        let entries;
        bracketed!(entries in input);
        let mut categories: Vec<GroupedRequestResponseCategoryRustStructNames> = Vec::new();
        while !entries.is_empty() {
            let name: Ident = parse_property_colon_member::<kw::group_name, syn::Ident>(&input)?;
            let span = name.span();
            let category = GroupedRequestResponseCategoryRustStructNames::new(name);
            let normalized = category.pascal().to_string();
            if categories.iter().any(|existing| existing.pascal().to_string() == normalized) {
                return Err(syn::Error::new(span, format!("duplicate category name `{normalized}`")));
            }
            categories.push(category);
            if entries.is_empty() {
                break;
            }
            entries.parse::<Token![,]>()?;
        }
        Ok(Self { categories })
    }
}

impl Unparse for GroupedRequestResponseCategoryRustStructGenerator {
    /// Re-emit `[ CategoryName, ... ]` so the list can be parsed again.
    fn unparse(&self) -> TokenStream {
        let names = self.categories.iter().map(GroupedRequestResponseCategoryRustStructNames::pascal);
        quote! {
            [
                #( #names, )*
            ]
        }
    }
}

impl GroupedRequestResponseCategoryRustStructGenerator {
    /// Categories in template order.
    ///
    /// The snake_case form of each name is the category template macro to invoke.
    pub fn categories(&self) -> &[GroupedRequestResponseCategoryRustStructNames] {
        &self.categories
    }

    pub fn generate_generic_with_field_name_categories_and_of_type(&self, struct_name: &Ident) -> proc_macro2::TokenStream {
        // TODO pub / private, derives

        // Note using StructTemplate as this is using generics

        let mut fields = proc_macro2::TokenStream::new();

        for category in &self.categories {
            let field_name = category.snake();
            fields.extend(quote! {#field_name: T,
            })
        }

        quote! {
            pub struct #struct_name {
                #fields
            }
        }
    }
}

pub struct GroupedRequestResponseCategoryRustStructNames {
    base_category_pascal_name: Ident,
    template_macro_name: Ident
}

impl GroupedRequestResponseCategoryRustStructNames {
    /// Creates a new instance, enforcing pascal casing
    pub fn new(base_name: Ident, template_macro_name: Ident) -> Self {
        let value = base_name.to_string();
        let pascal = value.to_pascal_case();
        Self {
            base_category_pascal_name: format_ident!("{}", pascal),
            template_macro_name
        }
    }

    /// Get pascal name
    pub fn pascal(&self) -> Ident {
        self.base_category_pascal_name.clone()
    }

    /// Get snake name
    pub fn snake(&self) -> Ident {
        let value = self.base_category_pascal_name.to_string();
        let value = value.to_snake_case();
        format_ident!("{}", value)
    }

    /// Template macro exported for this category.
    ///
    /// This is the snake_case category ident, which is the `exported_macro_name` for that category.
    pub fn template_macro_name(&self) -> Ident {
        self.template_macro_name.clone()
    }

    /// The name of the enum request struct
    pub fn request_enum_name(&self) -> Ident {
        format_ident!("{}Requests", self.base_category_pascal_name)
    }

    /// The name of the enum response struct
    pub fn response_enum_name(&self) -> Ident {
        format_ident!("{}Responses", self.base_category_pascal_name)
    }
}
